package com.eventdrivencommerce.payment.infrastructure.outbox;
import org.apache.kafka.clients.producer.ProducerRecord;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.concurrent.TimeUnit;
@Component @ConditionalOnProperty(name="payment.outbox.publisher-enabled",havingValue="true",matchIfMissing=true)public class OutboxPublisher{private final SpringDataOutboxRepository repository;private final KafkaTemplate<String,String>kafka;private final Clock clock;private final String topic;private final int batch;private final Duration timeout;public OutboxPublisher(SpringDataOutboxRepository repository,KafkaTemplate<String,String>kafka,Clock clock,@Value("${payment.outbox.topic}")String topic,@Value("${payment.outbox.batch-size:50}")int batch,@Value("${payment.outbox.publish-timeout:PT10S}")Duration timeout){this.repository=repository;this.kafka=kafka;this.clock=clock;this.topic=topic;this.batch=batch;this.timeout=timeout;}@Scheduled(fixedDelayString="${payment.outbox.poll-interval:PT1S}")@Transactional public void publish(){for(var e:repository.lockPending(batch)){try{var record=new ProducerRecord<String,String>(topic,e.aggregateId.toString(),e.payload.toString());header(record,"eventId",e.eventId.toString());header(record,"eventType",e.eventType);header(record,"eventVersion","1");header(record,"correlationId",e.correlationId.toString());header(record,"causationId",e.causationId.toString());header(record,"contentType","application/json");header(record,"schema",e.eventType.replaceAll("([a-z])([A-Z])","$1-$2").toLowerCase()+".schema.json");header(record,"producer","payment-service");kafka.send(record).get(timeout.toMillis(),TimeUnit.MILLISECONDS);e.published(clock.instant());}catch(Exception ex){e.failed(clock.instant(),root(ex));}}}private static void header(ProducerRecord<String,String>r,String n,String v){r.headers().add(n,v.getBytes(StandardCharsets.UTF_8));}private static String root(Exception e){Throwable t=e;while(t.getCause()!=null)t=t.getCause();return t.getMessage();}}
